#include "runtime/interpreter.hpp"
#include <chrono>
#include <iostream>
namespace {int checks=0;void run(const std::string& source,const penta::runtime::ExecutionOptions& options,bool success=true){++checks;const auto result=penta::runtime::execute(source,{},options);if(result.ok()==success)return;for(const auto& d:result.analysis.diagnostics)std::cerr<<d.code<<": "<<d.message<<" near "<<source.substr(d.span.offset,100)<<'\n';for(const auto& d:result.runtimeDiagnostics)std::cerr<<d.code<<": "<<d.message<<" near "<<source.substr(d.span.offset,100)<<'\n';throw std::runtime_error("Public typed Tensor solver fixture failed");}}
int main(int argc,char**argv){penta::runtime::ExecutionOptions options;options.dataDirectory=std::filesystem::temp_directory_path()/("penta-tensor-solvers-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));std::filesystem::create_directories(options.dataDirectory);options.odeCacheDirectory=options.dataDirectory/"kernels";if(argc>1)options.numericModuleDirectory=std::filesystem::absolute(argv[1]);try{
    run(R"(native function tensor<2,1,1> cubes(tensor<2,1,1> x){return x.*x.*x;}native function real energy(tensor<2,1,1> x){return x(1)^3+x(2)^3;}tensor<2,1,1> point=tensor([2,3],[2,1,1]);tensor<2,1,1> direction=tensor(1.0,[2,1,1]);assert(norm(jacobian(cubes,point)-[12,0;0,27],"fro")<1e-11);assert(norm(gradient(energy,point)-[12;27])<1e-11);assert(norm(hessian(energy,point)-[12,0;0,18],"fro")<1e-11);assert(norm(hvp(energy,point,direction)-[12;18])<1e-11);assert(norm(jvp(cubes,point,direction)-[12;27])<1e-11);assert(norm(vjp(cubes,point,direction)-[12;27])<1e-11);record third_result=thirdderivative(cubes,point,direction,direction,direction);assert(norm(third_result.third-[6;6])<1e-11);record scalar_third=thirdderivative(energy,point,direction,direction,direction);assert(abs(scalar_third.third(1)-12)<1e-11);)",options);
    run(R"(native function tensor<2,1,1> residual(tensor<2,1,1> x){return x-tensor([1,-2],[2,1,1]);}tensor<2,1,1> point=tensor([2,3],[2,1,1]);record solved=rootsolve(residual,point,options(ftol=1e-11));assert(solved.converged);assert(norm(solved.x-tensor([1,-2],[2,1,1]))<1e-8);assert(tensorinfo(solved.x).rank==3);)",options);
    run(R"(native function real objective(tensor<2,1,1> x){return (x(1)-1)^2+(x(2)+2)^2;}tensor<2,1,1> point=tensor([2,3],[2,1,1]);record solved=minimize(objective,point,options(algorithm="lbfgs"));assert(norm(solved.x-tensor([1,-2],[2,1,1]))<1e-7);assert(tensorinfo(solved.x).rank==3);)",options);
    run(R"(native function tensor<2,1,1> residual(tensor<2,1,1> x){return x-tensor([1,-2],[2,1,1]);}tensor<2,1,1> point=tensor([2,3],[2,1,1]);record solved=lsqfit(residual,point);assert(norm(solved.x-tensor([1,-2],[2,1,1]))<1e-6);assert(tensorinfo(solved.x).rank==3);)",options);
    run(R"(native function tensor<2,1,1> contract(tensor<2,1,1> x){return x*0.5+tensor([0.5,-1.0],[2,1,1]);}tensor<2,1,1> point=tensor([2,3],[2,1,1]);record mapped=mapiterate(contract,point,options(iterations=3));assert(norm(mapped.x-(tensor([1,-2],[2,1,1])+(point-tensor([1,-2],[2,1,1]))*0.125))<1e-11);record fixed=fixedpoint(contract,point);assert(norm(fixed.x-tensor([1,-2],[2,1,1]))<1e-7);)",options);
    run(R"(native function real objective(tensor<2,1,1> x){return (x(1)-1)^2+(x(2)+2)^2;}tensor<2,1,1> point=tensor([2,3],[2,1,1]);record solved=evolve(objective,point,options(algorithm="jde",lower=-4,upper=4,population=8,max_generations=2,seed=3));assert(tensorinfo(solved.x).rank==3);assert(solved.objective>=0);)",options);
    run(R"(native function real objective(tensor<2,1,1> x){return x(1)^2+x(2)^2;}tensor<1,2,1> wrong=tensor(1.0,[1,2,1]);matrix rejected=gradient(objective,wrong);)",options,false);
    run(R"(native function real objective(tensor<2,1,1> x){return x(1)^2+x(2)^2;}tensor<2,1,1> point=tensor(1.0,[2,1,1]);tensor<1,2,1> wrong=tensor(1.0,[1,2,1]);matrix rejected=hvp(objective,point,wrong);)",options,false);
    run(R"(native function real objective(tensor<2,1,1> x){return x(1)^2+x(2)^2;}native function real constraint(tensor<1,2,1> x){return x(1)-1.0;}tensor<2,1,1> point=tensor(1.0,[2,1,1]);record rejected=minimize(objective,point,options(algorithm="slsqp",inequality=constraint));)",options,false);
    std::cout<<"PASS "<<checks<<" public typed Tensor derivative/solver language checks\n";
}catch(const std::exception&e){std::cerr<<"FAIL after "<<checks<<": "<<e.what()<<'\n';return 1;}std::error_code ignored;std::filesystem::remove_all(options.dataDirectory,ignored);}
